\label{d2thm} Let $f(z)$ be a  Hecke eigencuspform  of level $1$ either holomorphic of weight $k\geqslant 2$ or a Laplacian eigenform with spectral parameter $t_f$; let $(\lambda_f(n))_{n\geqslant 1}$ be its Hecke eigenvalues. Let $q=q_0q_1$ be a product of two distinct primes and let $$K_0:\mathbf{Z}/{q_0}\mathbf{Z}\mapsto \mathbf{C},\ K_1:\mathbf{Z}/{q_1}\mathbf{Z}\mapsto \mathbf{C}$$ be two complex valued functions which we identify with functions on $\mathbf{Z}$ of period $q_0$ and $q_1$ respectively;  we assume that $K_0$ is the trace function attached to an $\ell$-adic middle extension Fourier sheaf $\mathcal{F}$ on $\mathbf{A}^1_{\mathbf{F}_{q_0}}$, geometrically irreducible, pure of weight $0$ and such that
 \begin{itemize}
 \item The automorphism group {\rm(}see \cite[\S 7.1]{FKMS}{\rm)} of the Fourier transform sheaf $\widehat\mathcal{F}$  is trivial.
     \item {\rm (MO)}  {\rm(}see \cite[\S 1]{LMS}{\rm)} There is no $ \lambda \in {\mathbf{F}^\times_q}$ such that the geometric monodromy group of $\mathcal{F}$ has some quotient which is equal, as a representation of the geometric fundamental group $\pi_1$ into an algebraic group, to the geometric monodromy group of the Kloosterman sheaf $[\times \lambda]^*\mathcal{K}\ell_2$ modulo $\pm 1$.

 \end{itemize}

 Let $K$ be the $q$-periodic function given by
$$
K(\cdot)=K_0(\cdot)K_1(\cdot).$$

Let $Z\geqslant 1$ be some parameter and $V\in \mathcal{C}^\infty_c(\mathbf{R})$ be a smooth function compactly supported in the interval $[1,2[$ satisfying for all $j\geqslant 0$,
\begin{equation}\label{bound-of-V}
    V^{(j)}(x)\ll_j Z^j.
\end{equation}

For $X\geqslant 1$ we have the bound   
\begin{equation}
	\label{d2boundcomposite}
	\sum_{n=1}^{\infty}\lambda_f(n)K(n)V\left(\frac{n}{X}\right)\ll  \|\widehat{K_1}\|_{\infty} X^{o(1)}\left(  Z^{1/2}X^{1/2} q_0^{1/2}+ZX^{1/2}q^{1/2}{q_0}^{-1/4}+  Zq^{1/2}{q_0}^{1/4}\right),
\end{equation}
where the implicit constant depends at most on $f$, on the conductor $C_0=C(\mathcal{F})$ of $\mathcal{F}$ and on the implicit constants in \eqref{bound-of-V}.

In particular, under the above assumptions on $K$, for $Z=1$ and
$$q_0= q^{2/3+o(1)}$$ 
from \eqref{d2boundcomposite} we see that the bound \eqref{nontrivialgeneric} holds as long as
\begin{equation*}\label{Weylrange}
	X\geqslant q^{2/3+\delta}
\end{equation*} for any given $\delta>0$. The range (for $d=2$) $$q^{2/3}=X_{\mathrm{cv}}^{2/3}>X_{\mathrm{ap}}=q^{1/2}$$  is sometimes called the {\em Weyl range}. It can be related to the work of Heath-Brown  \cite{H-B78} who obtained a Weyl-type subconvexity bound $L(\chi,1/2)=O\big(q^{1/6+o(1)}\big)$ for the Dirichlet $L$-functions provided that $q$ has a factor $q_0$ of size $q_0\approx q^{2/3}$.

\label{van der Corput}
 It is possible to improve this range further assuming that $q_0$ is squarefree and suitably factorable (under additional assumptions on $K_0$) by using the
    recent work of Wu, Xi, and Sawin \cite{PW} which extends Heath-Brown's $q$-van der Corput's method to general trace functions.

\label{mainarith} 

Notations be as above. Assume that $$q_0= q^{4/5+o(1)}.$$
We have for any $(a,q)=1$,
$$\sum_{\stackrel{{\scriptstyle n,|r|\geqslant 1}}
{{\scriptstyle nr^2\equiv a\bmod q}}}\lambda_\varphi(n,r)\lambda_f(n)V\left(\frac{nr^2}{X}\right)\ll_{\varphi,f} X^{o(1)}\left(X^{1/4}q^{8/5}+q^{23/10}\right).$$
In particular, given $\eta>0$,  we have
$$\sum_{\stackrel{{\scriptstyle n,|r|\geqslant 1}}
{{\scriptstyle nr^2\equiv a\bmod q}}}\lambda_\varphi(n,r)\lambda_f(n)V\left(\frac{nr^2}{X}\right)\ll_{\varphi,f,\eta}  (\frac{X}{q})^{1-\delta}$$
for some $\delta=\delta(\eta)>0$ as long as
$$q\leqslant X^{2/7+1/364-\eta}=X^{\theta_6+1/364-\eta}.$$

Estimating trivially (assuming the sum over $\alpha\bmod q_0$ in \eqref{main+errors} is 
 bounded above by $O(q_0^{1/2})$) and ignoring the error terms, we have
\begin{equation*}
\begin{split}
    S(X)\ll& \frac{X^{2+o(1)}}{P^3{q_0}^2q^{1/2} }\frac{p^2{q_0}^2}{X}P\frac{Zpq}{X}q_0^{1/2}
    \ll X^{o(1)}ZPq^{1/2}q_0^{1/2}.
    \end{split}\end{equation*}
    In view of the constraint \eqref{initial-assumption}, this bound is insufficient to beat the trivial bound $O(X)$ yet.

\label{bound-k-part}
 We have the following estimates
\begin{equation*}
\mathrm{FT}(0;k)\ll \sqrt{k}rc_1c_2\mathop{\sum_{d|c_1c_2}\sum_{d'|c_1c_2}}_{(d,d')|(m  -m')} (d ,d'),
\end{equation*}
and
\begin{equation*}
\begin{split}
\mathrm{FT}(n;k)\ll \sqrt{k}\sum_{d_1|c_1}d_1\sum_{d'_1|c_1}d'_1
\mathop{\sideset{}{^\star}\sum_{\stackrel{{\scriptstyle x_1(rc_1/n_1)}}
{{\scriptstyle q^2_1  n_1x_1\equiv \mp m\bmod {d_1}}}}}\mathop{\sum\sum}\limits_{\stackrel{{\scriptstyle d_2|(c_2,q^2_1 n_1c'_2+nm)}}
{{\scriptstyle d'_2|(c'_2,q^2_1 n_1c_2+nm')}}}d_2d'_2.
\end{split}\end{equation*}
